function navigate(value){const hash=value.startsWith('#')?value:'#'+value;if(location.hash===hash){render(true);}else{location.hash=hash;render();}}
function render(force=false){if(!data)return;const routeKey=location.hash||'#/';if(force!==true&&main.dataset.route===routeKey)return;tenderController?.abort();tenderController=null;let route;try{route=routeFrom(location.hash);}catch{route={page:'not-found'};}document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===route.page||(['investigation','reporting-question','audits','governance','cash-bridge'].includes(route.page)&&a.dataset.nav==='home')||(['record','tenders','municipal','budget-tables','transfers','institution','authorizations'].includes(route.page)&&a.dataset.nav==='money');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const pages={home,sources,money,tenders,municipal,audits,transfers,institution,authorizations,'cash-bridge':cashBridge,'budget-tables':budgetTables,record,investigation,'reporting-question':reportingQuestion,governance:governanceCase,methods,'not-found':()=>notFound()};main.replaceChildren(...pages[route.page](route));main.dataset.route=routeKey;main.dataset.renderVersion=String(Number(main.dataset.renderVersion||0)+1);document.title=`${({home:'Investigations',sources:'Sources & coverage',money:'Follow the money',methods:'How we work',investigation:'Evidence file','reporting-question':'Reporting question',governance:'Governance evidence',record:'Financial record',tenders:'Tender observations',municipal:'Historical municipal finances',audits:'Historical audit follow-up','budget-tables':'Budget table cells',transfers:'Federal transfer program trace',institution:'Institutional financial statements',authorizations:'Supplemental appropriation orders','cash-bridge':'Cash and annual-result explanation'})[route.page]||'Not found'} · HalifaxData`;window.scrollTo(0,0);main.focus({preventScroll:true});}
window.addEventListener('hashchange',()=>render());
try{publicationReview=await verifiedJSON('data/publication-review.json',null,null);if(publicationReview.status!=='accepted'||!/^[a-f0-9]{64}$/.test(publicationReview.bundleSha256))throw new Error('Publication review not accepted');data=validateBundle(await verifiedJSON('data/foundation.json',publicationReview.bundleSha256,null));reporting=await getReporting(null);governance=await getGovernance(null);coverage=await getCoverage(data.sources.map(s=>s.id),null);document.getElementById('release-label').textContent=`Fresh foundation · evidence reviewed ${data.asOf}`;render();}catch(error){main.replaceChildren(el('section',{class:'error',role:'alert'},paragraph('EVIDENCE UNAVAILABLE','eyebrow'),el('h1',{},'We could not load the records.'),paragraph('No numbers or findings are being shown. Please reload to try again; unavailable data must not be mistaken for zero activity.'),el('button',{class:'button',onclick:()=>location.reload()},'Reload evidence')));console.error(error);}
